def Eq(a,b):return {'type':'Eq','a':a,'b':b}
def Not(x):return {'type':'Not','arg':x}
def And(*xs):return {'type':'And','items':list(xs)}
def Or(*xs):return {'type':'Or','items':list(xs)}
def Lt(a,b):return {'type':'Lt','a':a,'b':b}
def Gt(a,b):return {'type':'Gt','a':a,'b':b}
def Plus(*xs):return {'type':'Plus','items':list(xs)}
def Concat(*xs):return {'type':'StringConcat','parts':list(xs)}
def Exists(source,var,pred):return {'type':'Exists','source':source,'var_name':var,'predicate':pred}
